 reset(){this.energyEffects.reset();this.targetPrevious=null;this.targetVelocity=new THREE.Vector3();this.skippedAim=0;this.directShots=this.leadShots=0;this.orbs=[];this.plan=[];this.barragePlanned=0;this.emitted=this.clearedSafe=this.deflected=this.splits=this.curves=0;this.mesh.count=this.outline.count=this.halo.count=this.debugMesh.count=0;}
