   if(orb.kind==='mines'&&orb.stationary&&orb.age>=c.mines.armingSeconds){if(orb.warning<0&&(distance<c.mines.triggerDistance||orb.age>=c.mines.fuse))orb.warning=c.mines.triggerWindup;if(orb.warning>=0){orb.warning-=dt;if(orb.warning<=0){if(distance<c.mines.blastRadius&&!this.safe(target,target))b.playerHit(orb.position,c.projectiles.damage);b.effects?.impact(orb.position,'#ffad50',2);this.split(orb,'mine-shard',c.mines.burstCount,c.mines.burstSpeed,Math.PI*2/c.mines.burstCount);continue;}}}
   if(orb.canCurve){if(orb.warning<0&&distance<c.curve.triggerDistance){orb.warning=c.curve.warningSeconds;orb.curveTarget=target.clone();this.curves++;}else if(orb.warning>=0){orb.warning=Math.max(0,orb.warning-dt);if(orb.warning===0&&orb.turned<c.curve.turnSeconds){const direction=orb.velocity.clone().normalize(),desired=orb.curveTarget.clone().sub(orb.position).normalize(),angle=direction.angleTo(desired),axis=new THREE.Vector3().crossVectors(direction,desired).normalize();if(axis.lengthSq()>.01)direction.applyAxisAngle(axis,Math.min(angle,c.curve.turnRate*dt));const speed=orb.velocity.length();orb.velocity.copy(direction).multiplyScalar(Math.min(c.curve.maxSpeed,speed+c.curve.acceleration*dt));orb.turned+=dt;}}}
   const hit=dt>0?b.traceProjectile?.(orb.previous,orb.position,c.projectiles.radius):null;if(hit){this.energyEffects.impact(hit.point,orb.velocity.clone().normalize(),c.projectiles.radius);if(hit.barrier)hit.barrier.onHit?.(hit.point,c.projectiles.damage);if(hit.unit?.kind==='hero')b.playerHit(hit.point,c.projectiles.damage);b.onProjectileImpact?.(hit);this.remove(orb);continue;}
