 render(time){const c=this.config;let i=0,outlined=0;for(const orb of this.orbs){const color=new THREE.Color(orb.friendly?'#79ffdd':orb.warning>=0&&orb.warning>0?'#fff3b0':orb.kind==='mines'?'#ffb23b':orb.kind==='lattice'?'#d2a0ff':orb.kind==='curve'?'#ff5da2':orb.kind==='gatling'?'#ffdfa0':'#ff784b');this.dummy.position.copy(orb.position);this.dummy.scale.setScalar(c.projectiles.radius*(orb.kind==='mines'?1.35:1));this.dummy.quaternion.identity();if(orb.kind==='gatling'){this.dummy.quaternion.setFromUnitVectors(new THREE.Vector3(0,0,1),orb.velocity.clone().normalize());this.dummy.scale.z*=c.gatling.trailLength;}this.dummy.updateMatrix();this.mesh.setMatrixAt(i,this.dummy.matrix);this.debugMesh.setMatrixAt(i,this.dummy.matrix);this.mesh.setColorAt(i,color);if(orb.kind==='gatling'){this.dummy.scale.multiplyScalar(c.gatling.outlineScale);this.dummy.updateMatrix();this.outline.setMatrixAt(outlined++,this.dummy.matrix);this.dummy.scale.multiplyScalar(1/c.gatling.outlineScale);}this.dummy.scale.multiplyScalar((orb.kind==='gatling'?c.gatling.haloScale:2.1)+Math.sin(time*16+orb.id)*(orb.kind==='gatling'?.08:.18));this.dummy.updateMatrix();this.halo.setMatrixAt(i,this.dummy.matrix);this.halo.setColorAt(i,color);i++;}this.outline.count=outlined;this.outline.instanceMatrix.needsUpdate=true;this.mesh.count=this.halo.count=this.debugMesh.count=i;this.debugMesh.instanceMatrix.needsUpdate=true;this.mesh.instanceMatrix.needsUpdate=this.halo.instanceMatrix.needsUpdate=true;if(i){this.mesh.instanceColor.needsUpdate=this.halo.instanceColor.needsUpdate=true;}}
